def reachable(graph, start, goal):
    todo, seen = [start], {start}
    while todo:
        n = todo.pop()
        if n == goal:
            return True
        for m in graph.get(n, []):
            if m not in seen:
                seen.add(m)
                todo.append(m)
    return False

